template <typename T, typename Alloc = std::allocator<T>>
class CustomString {
    Alloc alloc_;
    size_t size_;

public:
    // Ctor demonstrating optional size/count and optional allocator
    // Uses default template parameter Alloc if none specified
    CustomString(
        size_t count = 0,
        const T& value = T{},
        const Alloc& alloc = Alloc{}
    ) : alloc_(alloc), size_(count)
    {
        if (count > 0)
            alloc_.allocate(count); // Simulate memory acquisition
    }
};
